use super::Track;

macro_rules! sources {
    ($(($id:literal, $name:literal, $category:literal, $character:literal, $seconds:literal, $bpm:literal, $asset:literal)),* $(,)?) => {
        pub(super) const TRACKS: [Track; 256] = [$(Track { id: $id, name: $name, category: $category, character: $character, seconds: $seconds, bpm: Some($bpm), asset: Some($asset) }),*];
        #[cfg(not(target_arch = "wasm32"))]
        pub(super) fn bytes(index: usize) -> &'static [u8] {
            const WAVS: &[&[u8]] = &[$(include_bytes!(concat!("../../assets/samples/", $asset))),*];
            WAVS[index]
        }
    };
}

